// Mapowanie symboli kraju na pełne nazwy (case-insensitive)
const countryCodeToName = {
  CZ: 'Czechy',
  SK: 'Słowacja',
  HU: 'Węgry',
  RO: 'Rumunia',
  BG: 'Bułgaria',
  PL: 'Polska',
};

// Fallback: waluta -> kraj (tylko dla walut jednoznacznych, NIE EUR)
const currencyToCountry = {
  CZK: 'Czechy',
  HUF: 'Węgry',
  RON: 'Rumunia',
};

const data = $json;
const waluta = (data['waluta obca [CZK, EUR, RON, HUF]'] || 'PLN').toString().toUpperCase();
const isPLN = waluta === 'PLN';

// 1. Sprawdź kolumnę Kraj (zawiera symbol: CZ, SK, BG, etc.)
const krajSymbol = (data['Kraj'] || data['Kraj kupującego'] || data['Symbol kraju kupującego'] || '').toString().toUpperCase().trim();

// 2. Mapuj symbol na pełną nazwę
let kraj = countryCodeToName[krajSymbol] || '';

// 3. Fallback: waluta -> kraj (tylko dla walut jednoznacznych, NIE EUR)
if (!kraj) {
  kraj = currencyToCountry[waluta] || (waluta === 'EUR' ? 'Słowacja' : 'Polska');
}

// Data wystawienia = ostatni dzień BIEŻĄCEGO miesiąca
const now = new Date();
const lastDayOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
const dataWystawienia = lastDayOfMonth.toISOString().split('T')[0];

// Data sprzedaży
const dataSprzedazy = (data['Data sprzedaży1'] || '').split('T')[0];

// Kwoty
const prowizja = parseFloat(data.prowizja) || 0;
const kurs = parseFloat(data.Kurs) || 1;
const kwotaWaluty = isPLN ? prowizja : (prowizja / kurs);

// Wspólna struktura faktury
const fakturaData = {
  Zaplacono: isPLN ? prowizja.toString() : kwotaWaluty.toFixed(2),
  LiczOd: 'BRT',
  DataWystawienia: dataWystawienia,
  MiejsceWystawienia: 'Chorowice',
  DataSprzedazy: dataSprzedazy,
  FormatDatySprzedazy: 'DZN',
  SposobZaplaty: 'PRZ',
  NazwaSeriiNumeracji: 'default',
  RodzajPodpisuOdbiorcy: 'OUP',
  PodpisOdbiorcy: 'Odbiorca',
  PodpisWystawcy: 'Wystawca',
  Pozycje: [{
    StawkaVat: 0.23,
    Ilosc: 1,
    CenaJednostkowa: isPLN ? prowizja.toString() : kwotaWaluty.toFixed(2),
    NazwaPelna: `${data['Nazwa towaru lub usługi'] || 'Pośrednictwo w sprzedaży'}-${data.Przedmiot || ''}`,
    Jednostka: 'sztuk',
    TypStawkiVat: 'PRC'
  }],
  Kontrahent: {
    Nazwa: data['Kupujący'] || '',
    Ulica: data['Ulica numer'] || '',
    KodPocztowy: data['Kod pocztowy'] || '',
    Kraj: kraj,
    Miejscowosc: data['Miejscowość'] || '',
    OsobaFizyczna: true
  }
};

// Dodatkowe pola dla faktur walutowych
if (!isPLN) {
  fakturaData.TypSprzedazy = 'WYSYLKOWA';
  fakturaData.Jezyk = 'en';
  fakturaData.Waluta = waluta;
  fakturaData.KursWalutyWidoczny = true;
  fakturaData.KursWalutyZDniaPoprzedzajacegoDzienWystawieniaFaktury = kurs.toString();
  fakturaData.WidocznyNumerGios = false;
  fakturaData.WidocznyNumerBdo = false;
  fakturaData.Numer = null;
}

return [{
  json: {
    isPLN: isPLN,
    orderId: data.ID,
    nazwaUsera: 'mdz-invest1',
    nazwaKlucza: 'faktura',
    kluczAPI: '14A91FBA6257DC4A',
    url: isPLN ? 'https://www.ifirma.pl/iapi/fakturakraj.json' : 'https://www.ifirma.pl/iapi/fakturawaluta.json',
    fakturaData: fakturaData,
    originalData: data
  }
}];

const crypto = require('crypto');

const input = $json;

if (!input.kluczAPI || !input.fakturaData || !input.url) {
  return [{ json: { error: 'Missing required fields', input: input } }];
}

try {
  const kluczAPI = input.kluczAPI.trim();
  const fakturaData = input.fakturaData;
  const url = input.url;
  const nazwaUsera = input.nazwaUsera;
  const nazwaKlucza = input.nazwaKlucza;

  const hexKey = Buffer.from(kluczAPI, 'hex');
  const requestContent = JSON.stringify(fakturaData);
  const message = url + nazwaUsera + nazwaKlucza + requestContent;
  const hash = crypto.createHmac('sha1', hexKey).update(message).digest('hex');
  const authHeader = `IAPIS user=${nazwaUsera}, hmac-sha1=${hash}`;

  return [{
    json: {
      authentication: authHeader,
      requestData: fakturaData,
      url: url,
      isPLN: input.isPLN,
      orderId: input.orderId
    }
  }];
} catch (error) {
  return [{ json: { error: error.message, input: input } }];
}
